fn permutation(cell:usize, mut s:[u64;16])->[u64;16] {
 println!("{} {} {:?}",cell,0,s);s=ext(s);println!("{} {} {:?}",cell,1,s);
 for j in 0..4{s=full(s,&INITIAL[16*j..16*j+16]);println!("{} {} {:?}",cell,j+2,s);}
 for j in 0..14{s=internal(s,INTERNAL[j]);println!("{} {} {:?}",cell,j+6,s);}
 for j in 0..4{s=full(s,&FINAL[16*j..16*j+16]);println!("{} {} {:?}",cell,j+20,s);}
 s
}
fn absorb(mut s:[u64;16],x:[u64;8])->[u64;16]{for i in 0..8{s[i]=add(s[i],x[i]);}s}
fn init(domain:u64,len:u64)->[u64;16]{let mut s=[0;16];s[8]=domain;s[9]=len;s}
fn digest(seed:u64)->[u64;8]{core::array::from_fn(|i|seed+17*i as u64+1)}

fn node(cell:usize,left:[u64;8],right:[u64;8])->[u64;8] {
 let mut pre=[0;16];pre[..8].copy_from_slice(&left);pre[8..].copy_from_slice(&right);pre[15]=add(pre[15],0x41531005);
 let s=permutation(cell,pre);let mut d=[0;8];d.copy_from_slice(&s[..8]);d
}
